import type { ModelClientId, ToolId } from "@agentplugged/protocol";
import {
  ANTIGRAVITY_HOOK_PATH,
  ANTIGRAVITY_HOOKS_PATH,
  ANTIGRAVITY_MCP_CONFIG_PATH,
  ANTIGRAVITY_POLICY_PATH,
} from "../chat/antigravity-hook.js";
import { CODEX_HOOK_PATH, CODEX_POLICY_PATH, CODEX_RULES_PATH } from "../chat/codex-hook.js";
import { CURSOR_HOOK_PATH, CURSOR_HOOKS_PATH, CURSOR_POLICY_PATH } from "../chat/cursor-hook.js";
import { CURSOR_CLI_PATH, CURSOR_IGNORE_PATH } from "./targets/cursor.js";

/**
 * What an AI tool reads from the project. Each target is generated by `sync` (native), or covered
 * by a fallback: the tool follows the constitution without a technical guard.
 */
export const CAPABILITIES = [
  "skills",
  "agents",
  "instructions",
  "permissions",
  "model",
  "mcp",
  "rules",
  /** The trace of what a session read from outside: a hook records it in the journal. */
  "untrusted",
  /** The proof of the chat's answers: a hook records the creator's messages. */
  "chat_proof",
  "isolation",
  /**
   * Decisions asked by the engine itself, to click: the tool shows the forms the MCP
   * server asks for (elicitation) or, for Claude Code in the VS Code extension, its question tool
   *. In a fallback, the agent asks the question in text.
   */
  "decisions",
  /**
   * The installations: at the `visible` installs mode (the default) they go
   * through and show in the activity and the journal; at `validate` a hook asks the creator first.
   * In a fallback, the tool has no such hook: they are neither recorded nor validated by the engine.
   */
  "installs",
  /**
   * What the sessions of the tool consumed, measured by the engine from the traces the tool keeps on
   * the machine: tokens, models, time. In a fallback the engine measures
   * nothing, and never estimates.
   */
  "usage",
] as const;
export type Capability = (typeof CAPABILITIES)[number];

/**
 * A client of the method: one AI tool as it reads the project.
 */
export type ClientId = ModelClientId;

/**
 * Why a tool has the "model" fallback: the model table gives `inherit` for one of its tiers, so
 * those agents run on the model of the session.
 */
export const MODEL_INHERIT_REASON =
  "the model table (`.agentplugged/models.yaml`, or `models` in `method.yaml`) gives `inherit` for at least one model tier: agents of that tier use the model of the session.";

/**
 * Why Codex has the "rules" fallback: its hooks answer `allow` or `deny`, never `ask`.
 * What the product denies is refused (the hook, and the rules of commands Codex applies itself).
 */
export const CODEX_RULES_REASON =
  "Codex's hooks answer `allow` or `deny`, never `ask`: a permission rule that asks (`ask`, which only the creator sets) is written as a `prompt` rule in `.codex/rules/agentplugged.rules` only while Codex asks for approvals (the `strict` level, edits that ask first): with no approval (the default, written as a granular `approval_policy` that still lets the forms through) Codex cannot ask, nothing is written, and the hook lets the call through. Before such an action, ask the creator in the chat. What the product denies (push to the main branch, force push, mass deletion, reading secrets, writing the product's protected files) is refused by the hook and, for commands, by Codex's own rules. `internet: ask` disables web search and keeps the sandbox offline; `edit_code: ask` or `deny` is a read-only sandbox with approval on request. The hooks run only once the creator has approved them (`/hooks` in Codex, once).";

/**
 * Why a tool without hooks has the "untrusted" fallback (Claude Code, Antigravity CLI, Codex and
 * Cursor have hooks): no hook records what the session read from outside.
 */
export const UNTRUSTED_REASON =
  "agentplugged writes no hook for this tool: a read through the tool's web access or another MCP server is not recorded by itself. After reading external content, call `guard.external_read` so that the journal keeps the trace (source, time, agent); nothing is blocked for it. Actions through file tools (reading, editing, writing) are not seen by a read hook: they stay governed by the permission rules alone (`read_secrets` is always denied). Only Claude Code also checks a write before it happens (a secret, a file outside the story, a decision of the architecture): not this tool.";

/**
 * Why a tool without the hook has the "chat_proof" fallback (Claude Code, Antigravity CLI, Codex and
 * the Cursor editor have it): no hook records the creator's messages, so an answer given in the
 * chat is recorded unverified.
 */
export const CHAT_PROOF_REASON =
  "agentplugged writes no hook that records the creator's messages for this tool: an answer the creator gives in the chat is recorded « unverified » (`chat_unverified`) and shown so everywhere, whatever the point (the journal keeps the trace of every answer). For every answer to be checked, the creator works in Claude Code; for high-risk checkpoints to go through the creator's key, they choose the `strict` level.";

/**
 * Why Codex has the "untrusted" fallback: its hooks see a network command and the tools
 * of another MCP server, not its own web search (a hosted tool).
 */
export const CODEX_UNTRUSTED_REASON =
  "Codex's hooks record a read made through a network command (`curl`, `wget`, `gh`, `git pull`…) or a tool of another MCP server. Codex's own web search is a hosted tool that hooks do not see: after a web search, call `guard.external_read` so that the journal keeps the trace (source, time, agent); nothing is blocked for it. Actions through file tools (reading, editing, writing) are not seen by a read hook: they stay governed by the permission rules alone (`read_secrets` is always denied). Only Claude Code also checks a write before it happens (a secret, a file outside the story, a decision of the architecture): not this tool.";

/**
 * Why Cursor has the "rules" fallback (Cursor 3.23.12): its hooks act on `deny`, and on
 * `ask` for a shell command only (read in Cursor's code and in its documentation).
 */
export const CURSOR_RULES_REASON =
  "Cursor's hooks refuse what the product denies (push to the main branch, force push, mass deletion, writing the product's protected files, running another Cursor agent) and ask for a shell command that a rule asks for (`ask`), in the editor and in the command line when it emits the hook. They do not ask before a file write or a web access (`preToolUse` ignores `ask`): a rule that asks first for a file edit (`edit_code: ask`) or for the web (`internet: ask`) is not asked by Cursor, so before such an action ask the creator in the chat; `internet: deny` and `edit_code: deny` are refused. Cursor's own tools that read a file are not seen by a hook: `.cursorignore` keeps the secrets (`.env` and its kin) out of the agent's reach, and a command that reads one is refused. Text typed into a shell that is already running is not seen either. The hooks run only in a workspace the creator trusts.";

/**
 * Why Cursor has the "decisions" fallback (Cursor 3.23.12, documentation of 2026-10-07):
 * Cursor lists the forms an MCP server asks for among what it supports, but reports show the form
 * not displayed in the editor on Windows, the call staying pending, and none was seen displayed in a
 * session of this product.
 */
export const CURSOR_DECISIONS_REASON =
  'Cursor lists the forms an MCP server asks for (elicitation) among what it supports, but reports from its own forum (Windows 11, Cursor 3.10.20, 2026-07-07, still seen on 3.17.8) show the form not displayed and the tool call staying pending, and none was seen displayed in a session of this product (Cursor 3.23.12, 2026-10-07): decisions are asked in text in the chat ("a, b or c?"), and the agent records the creator\'s answer with `chat.answer`, quoting it. The engine still tries the form first (`chat.ask`); in Cursor it waits 90 seconds for a first sign of life, and with none it asks in the chat for the rest of the session. A form that was answered once is waited for as long as in any other tool.';

/**
 * Why Cursor has the "usage" fallback: its local traces hold no token count, no model
 * and no date per line (read on a real transcript, 2026-10-07).
 */
export const CURSOR_USAGE_REASON =
  "Cursor keeps no token count anywhere on the machine: its transcripts (`~/.cursor/projects/<project>/agent-transcripts/`) hold the messages and the tool calls, with no tokens, no model and no date per line. The engine therefore measures nothing of a Cursor session (`measure.usage` answers `available: false`) and never estimates it; Cursor's own usage page (your account's dashboard) is the only source. The `stop` hook of the editor may carry token counts (seen in Cursor's own code, not verified filled): it is not used.";

/** Why a tool has the "usage" fallback: the engine reads none of its traces. */
export const USAGE_REASON =
  "the engine reads no trace of this tool: it measures nothing of its sessions (`measure.usage` answers `available: false`) and never estimates it.";

const CURSOR_DECISIONS_FALLBACK: CompatibilityCell = {
  support: "fallback",
  files: [],
  reason: CURSOR_DECISIONS_REASON,
};

/**
 * Why every tool but Claude Code has the "isolation" fallback: its agent files have
 * no setting that runs a developer in a worktree of its own.
 */
export const ISOLATION_REASON =
  "this tool's agent files cannot run a developer in a worktree of its own: each developer works only in the `workdir` that `story.start` returns, the story's own working copy, one per story.";

/**
 * Codex's "isolation" fallback: on top of the common reason, its sandbox keeps writes in
 * the project's folder, and a story's working copy sits next to it.
 */
export const CODEX_ISOLATION_REASON = `${ISOLATION_REASON} Codex's sandbox also keeps writes inside the project's folder, and a story's working copy sits next to it (\`<project>.worktrees/<id>\`): a developer can write there only if Codex's \`sandbox_workspace_write.writable_roots\` lists it, by its absolute path (observed on Codex 0.160.1, 2026-10-06: a relative path is read from the project's folder and its \`..\` is dropped; \`~/\` works): \`sync\` writes that folder in \`.codex/config.toml\` on each machine, so run \`sync\` again after moving the project. On Windows, Codex lets agents write in the project only once its Windows sandbox is set up (the elevated mode, one administrator approval, offered by the editor extension): otherwise the session silently falls back to read-only, and the unelevated mode refuses a project whose \`.git\` and \`.codex\` are protected.`;

const ISOLATION_FALLBACK: CompatibilityCell = {
  support: "fallback",
  files: [],
  reason: ISOLATION_REASON,
};

/**
 * Why a tool has the "decisions" fallback: it does not show, or not in every mode,
 * the forms an MCP server asks for (elicitation), so decisions are asked in text. Research of
 * 2026-10-04, to check again in each tool.
 */
export const DECISIONS_REASON =
  'this tool does not show the forms an MCP server asks for (elicitation), or not in every mode: decisions are asked in text in the chat ("a, b or c?"), and the agent records the creator\'s answer with `chat.answer`, quoting it. The engine still tries the form first (`chat.ask`) and falls back to the chat when the tool cannot show it.';

/**
 * Why Codex has the "decisions" fallback (research of 2026-10-06, Codex 0.160): forms an
 * MCP server asks for reach some of its surfaces, none was verified in a session of this product.
 */
export const CODEX_DECISIONS_REASON =
  'Codex sends the forms an MCP server asks for (elicitation) to its client only while its approval policy lets them through: a bare `never` declines them silently, which is why `sync` writes the granular form that refuses everything else (observed on Codex 0.160.1, 2026-10-06, through its app server: the request reaches the client, whose answer the engine records). `codex exec` declines them, and none was seen displayed on the screen of the editor extension: decisions are asked in text in the chat ("a, b or c?"), and the agent records the creator\'s answer with `chat.answer`, quoting it. The engine still tries the form first (`chat.ask`) and falls back to the chat when the tool cannot show it.';

const CODEX_DECISIONS_FALLBACK: CompatibilityCell = {
  support: "fallback",
  files: [],
  reason: CODEX_DECISIONS_REASON,
};

/**
 * Why a tool has the "installs" fallback: it has no hook that sees an
 * installation before it runs, so the engine neither records it in the activity nor validates it
 * (`installs.mode: validate`): the tool's own permissions decide.
 */
export const INSTALLS_REASON =
  "this tool has no hook that sees an installation before it runs: the engine does not record installations in the activity, and `installs.mode: validate` cannot ask for a validation here. The tool's own permissions decide.";

export interface CompatibilityCell {
  readonly support: "native" | "fallback";
  /**
   * Files `sync` generates for this capability; `<id>` stands for an agent identifier. A fallback
   * may come with files that cover part of the capability.
   */
  readonly files: readonly string[];
  /** Why a fallback is needed, in English (copied into the constitution). */
  readonly reason?: string;
}

export interface ClientCompatibility {
  readonly client: ClientId;
  /** The `tools` entry of `method.yaml` that generates this client's files. */
  readonly tool: ToolId;
  /** Product name, never translated. */
  readonly name: string;
  readonly cells: Readonly<Record<Capability, CompatibilityCell>>;
}

/**
 * The files of Antigravity CLI's plugin that guard the product: the rules (`policy.json`,
 * written from the lists of Claude Code's settings), the hooks that apply them and record the
 * creator's messages, and the script they run.
 */
const ANTIGRAVITY_GUARD_FILES = [
  ANTIGRAVITY_HOOKS_PATH,
  ANTIGRAVITY_POLICY_PATH,
  ANTIGRAVITY_HOOK_PATH,
];

/**
 * Why Antigravity CLI has the "decisions" fallback: its MCP client announces that it
 * shows forms (`elicitation`: `form` and `url`), but a form was only seen cancelled, in its
 * non-interactive mode (`agy -p`, version 1.2.16, 2026-10-04): showing one in a session is not verified yet.
 */
export const ANTIGRAVITY_DECISIONS_REASON =
  'Antigravity CLI announces that it shows the forms an MCP server asks for (elicitation), but that was verified only in its non-interactive mode, where it cancels them: until a session shows one, decisions are asked in text in the chat ("a, b or c?"), and the agent records the creator\'s answer with `chat.answer`, quoting it. The engine still tries the form first (`chat.ask`) and falls back to the chat when the tool cannot show it.';

/**
 * Why the plugin's capabilities are fallbacks when `.agents/plugins/agentplugged/` is the creator's
 *: `sync` wrote nothing there.
 */
export const ANTIGRAVITY_PLUGIN_KEPT_REASON =
  "`.agents/plugins/agentplugged/` is yours: sync wrote nothing there, so the `agentplugged` MCP server and the plugin's hooks (the permission rules, the reads of outside content, the proof of the chat) are not declared for Antigravity CLI. Rename or remove that folder, or add them yourself, then run `npx agentplugged sync` again.";

/** What Antigravity CLI's plugin brings: when the plugin is not written, these are fallbacks. */
const ANTIGRAVITY_PLUGIN_CAPABILITIES: readonly Capability[] = [
  "permissions",
  "rules",
  "untrusted",
  "chat_proof",
  "installs",
  "mcp",
];

const ANTIGRAVITY_DECISIONS_FALLBACK: CompatibilityCell = {
  support: "fallback",
  files: [],
  reason: ANTIGRAVITY_DECISIONS_REASON,
};

/** The files of Codex's guard: the project's hooks, their script and policy, the rules of commands. */
const CODEX_GUARD_FILES = [
  ".codex/config.toml",
  CODEX_HOOK_PATH,
  CODEX_POLICY_PATH,
  CODEX_RULES_PATH,
];

/**
 * What Codex's hooks bring: when `.codex/config.toml` is the creator's, `sync` declares no hook and
 * these are fallbacks.
 */
const CODEX_CONFIG_CAPABILITIES: readonly Capability[] = [
  "permissions",
  "rules",
  "untrusted",
  "chat_proof",
  "installs",
];

/**
 * The files of Cursor's guard: the project's hooks, their script and policy (the
 * `.cursorignore` that keeps the secrets from the agent and `.cursor/cli.json` come on top of them).
 */
const CURSOR_GUARD_FILES = [CURSOR_HOOKS_PATH, CURSOR_HOOK_PATH, CURSOR_POLICY_PATH];

/**
 * What Cursor's hooks bring: when `.cursor/hooks.json` is the creator's, `sync` declares no hook and
 * these are fallbacks.
 */
const CURSOR_HOOK_CAPABILITIES: readonly Capability[] = [
  "permissions",
  "rules",
  "untrusted",
  "chat_proof",
  "installs",
];

const SHARED_SKILLS: CompatibilityCell = {
  support: "native",
  files: [".agents/skills/<id>/SKILL.md"],
};

/**
 * Compatibility matrix of the four tools (documentation read on 2026-10-02; the `mcp` cells, the
 * project MCP configuration declaring the `agentplugged` server, on 2026-10-03; Codex's hooks, rules
 * and approvals, on 2026-10-06, Codex 0.160). It is data: the
 * generation tests walk every cell.
 */
export const COMPATIBILITY: readonly ClientCompatibility[] = [
  {
    client: "claude-code",
    tool: "claude-code",
    name: "Claude Code",
    cells: {
      skills: { support: "native", files: [".claude/skills/<id>/SKILL.md"] },
      agents: { support: "native", files: [".claude/agents/<id>.md"] },
      instructions: { support: "native", files: ["CLAUDE.md"] },
      permissions: { support: "native", files: [".claude/settings.json"] },
      model: { support: "native", files: [".claude/agents/<id>.md"] },
      mcp: { support: "native", files: [".mcp.json"] },
      rules: { support: "native", files: [".claude/settings.json"] },
      untrusted: { support: "native", files: [".claude/settings.json"] },
      chat_proof: {
        support: "native",
        files: [".claude/settings.json", ".claude/hooks/agentplugged-prompt.mjs"],
      },
      isolation: { support: "native", files: [".claude/agents/<id>.md"] },
      // The MCP server asks; Claude Code shows the form (elicitation) in the terminal. The VS Code
      // extension refuses the form at once (2.1.289): the engine then dictates the questions of
      // Claude Code's question tool, and a hook (`PostToolUse` on `AskUserQuestion`) records the
      // creator's answer, the proof.
      decisions: {
        support: "native",
        files: [".mcp.json", ".claude/settings.json", ".claude/hooks/agentplugged-decision.mjs"],
      },
      installs: {
        support: "native",
        files: [".claude/settings.json", ".claude/hooks/agentplugged-prompt.mjs"],
      },
      // Claude Code's transcripts, with the tokens of each answer.
      usage: { support: "native", files: [] },
    },
  },
  {
    client: "codex",
    tool: "codex",
    name: "Codex",
    cells: {
      skills: SHARED_SKILLS,
      agents: { support: "native", files: [".codex/agents/<id>.toml"] },
      instructions: { support: "native", files: ["AGENTS.md"] },
      // The sandbox (`config.toml`), the rules of commands Codex applies itself, and the hook that
      // applies the product's lists to a shell command and a patch.
      permissions: { support: "native", files: CODEX_GUARD_FILES },
      model: { support: "native", files: [".codex/agents/<id>.toml"] },
      mcp: { support: "native", files: [".codex/config.toml"] },
      rules: { support: "fallback", files: CODEX_GUARD_FILES, reason: CODEX_RULES_REASON },
      untrusted: { support: "fallback", files: CODEX_GUARD_FILES, reason: CODEX_UNTRUSTED_REASON },
      // The project's `UserPromptSubmit` hook records what the creator typed, as Claude Code's does
      // (same store, same rule); the creator approves the hooks once (`/hooks`).
      chat_proof: { support: "native", files: CODEX_GUARD_FILES },
      isolation: { support: "fallback", files: [], reason: CODEX_ISOLATION_REASON },
      decisions: CODEX_DECISIONS_FALLBACK,
      installs: { support: "native", files: CODEX_GUARD_FILES },
      // Codex's rollouts, read from the format observed on 0.160.1.
      usage: { support: "native", files: [] },
    },
  },
  {
    client: "antigravity",
    tool: "antigravity",
    name: "Antigravity CLI",
    cells: {
      skills: SHARED_SKILLS,
      agents: { support: "native", files: [".agents/agents/<id>.md"] },
      instructions: { support: "native", files: ["GEMINI.md"] },
      // No permission file in a project: the plugin's `PreToolUse` hook applies the rules.
      permissions: { support: "native", files: ANTIGRAVITY_GUARD_FILES },
      model: { support: "native", files: [".agents/agents/<id>.md"] },
      // Antigravity reads MCP servers from a global file or a plugin, never from the project's own file.
      mcp: { support: "native", files: [ANTIGRAVITY_MCP_CONFIG_PATH] },
      rules: { support: "native", files: ANTIGRAVITY_GUARD_FILES },
      untrusted: { support: "native", files: ANTIGRAVITY_GUARD_FILES },
      // The hook reads the conversation's transcript and records what the creator typed; seen working in an
      // interactive session on 2026-10-05 (the creator's own transcript). The app and the IDE are not covered, and
      // print mode is recorded like the rest (the transcript does not tell it apart): the trace, not the blocking.
      chat_proof: { support: "native", files: ANTIGRAVITY_GUARD_FILES },
      isolation: ISOLATION_FALLBACK,
      decisions: ANTIGRAVITY_DECISIONS_FALLBACK,
      installs: { support: "native", files: ANTIGRAVITY_GUARD_FILES },
      // Antigravity's conversation transcripts.
      usage: { support: "native", files: [] },
    },
  },
  {
    client: "cursor",
    tool: "cursor",
    name: "Cursor",
    cells: {
      skills: SHARED_SKILLS,
      agents: { support: "native", files: [".cursor/agents/<id>.md"] },
      instructions: { support: "native", files: ["AGENTS.md", ".cursor/rules/agentplugged.mdc"] },
      // The editor does not read `.cursor/cli.json` (the CLI does): the project's hooks apply the
      // product's lists to a command and a file write (`Write`, `Delete`) in both, `.cursorignore`
      // keeps the secrets from the agent's file tools.
      permissions: {
        support: "native",
        files: [...CURSOR_GUARD_FILES, CURSOR_CLI_PATH, CURSOR_IGNORE_PATH],
      },
      model: { support: "native", files: [".cursor/agents/<id>.md"] },
      mcp: { support: "native", files: [".cursor/mcp.json"] },
      // What the product denies is refused by the hooks, an `ask` of a command is asked; what Cursor
      // does not let a hook do is said: no `ask` before a file write, no hook on a read of a file.
      rules: {
        support: "fallback",
        files: [...CURSOR_GUARD_FILES, CURSOR_CLI_PATH],
        reason: CURSOR_RULES_REASON,
      },
      // Cursor's hooks see a web fetch, a web search, a network command and a tool of another MCP
      // server (`postToolUse`, `afterShellExecution`, `afterMCPExecution`).
      untrusted: { support: "native", files: CURSOR_GUARD_FILES },
      // The editor's `beforeSubmitPrompt` hook records what the creator typed, as Claude Code's does
      // (same store, same rule). The Cursor CLI (`cursor-agent`) does not emit that hook in the
      // versions seen (2026-08): its client is not a hooked one, and an answer given in the chat
      // there is recorded unverified, said so.
      chat_proof: { support: "native", files: CURSOR_GUARD_FILES },
      isolation: ISOLATION_FALLBACK,
      decisions: CURSOR_DECISIONS_FALLBACK,
      installs: { support: "native", files: CURSOR_GUARD_FILES },
      usage: { support: "fallback", files: [], reason: CURSOR_USAGE_REASON },
    },
  },
];

